import time
import math


class KVCache:
    def __init__(self, capacity, ttl_seconds, clock=None):
        if isinstance(capacity, bool) or not isinstance(capacity, int):
            raise ValueError("capacity must be a non-bool integer")
        if capacity < 0:
            raise ValueError("capacity must be >= 0")

        if isinstance(ttl_seconds, bool):
            raise ValueError("ttl_seconds must be a non-bool number")
        if not isinstance(ttl_seconds, (int, float)):
            raise ValueError("ttl_seconds must be a finite number")
        if isinstance(ttl_seconds, float) and not math.isfinite(ttl_seconds):
            raise ValueError("ttl_seconds must be finite")
        if ttl_seconds < 0:
            raise ValueError("ttl_seconds must be >= 0")

        self.capacity = capacity
        self.ttl_seconds = ttl_seconds
        self.clock = clock if clock is not None else time.monotonic
        # dict preserves insertion order; used to track LRU order (oldest first)
        self._store = {}

    def _now(self):
        return self.clock()

    def _is_expired(self, expiry, now):
        return now >= expiry

    def _purge_expired(self):
        now = self._now()
        expired_keys = [
            key for key, (value, expiry) in self._store.items()
            if self._is_expired(expiry, now)
        ]
        for key in expired_keys:
            del self._store[key]

    def _mark_used(self, key):
        # Move key to the end (most recently used position)
        value, expiry = self._store.pop(key)
        self._store[key] = (value, expiry)

    def get(self, key):
        if key not in self._store:
            return None
        value, expiry = self._store[key]
        now = self._now()
        if self._is_expired(expiry, now):
            del self._store[key]
            return None
        self._mark_used(key)
        return value

    def put(self, key, value):
        if self.capacity == 0 or self.ttl_seconds == 0:
            return
        now = self._now()
        expiry = now + self.ttl_seconds
        if key in self._store:
            self._store[key] = (value, expiry)
            self._mark_used(key)
            return
        # Evict expired entries first
        self._purge_expired()
        # Evict LRU entries if still over capacity
        while len(self._store) >= self.capacity:
            oldest_key = next(iter(self._store))
            del self._store[oldest_key]
        self._store[key] = (value, expiry)

    def delete(self, key):
        if key not in self._store:
            return False
        value, expiry = self._store[key]
        now = self._now()
        if self._is_expired(expiry, now):
            del self._store[key]
            return False
        del self._store[key]
        return True
